  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Ampicillin absolute oral bioavailability measured against IV in humans was 48.1 ± 19.3%, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Meperidine absolute oral bioavailability was 0.60 vs IV, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Diphenhydramine absolute oral bioavailability was 58% vs IV in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Felbamate absolute oral bioavailability was >90% in humans, strongly supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Perindopril absolute oral bioavailability was about 75% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Rivastigmine absolute oral bioavailability was 71.7% at 6 mg vs IV, supporting high oral bioavailability despite a wide reported range.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "PEMA absolute oral bioavailability was 91 ± 4.4% vs IV, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Carbamazepine epoxide oral bioavailability was at least 78%, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "DEHP oral bioavailability was ~25%, still above the 20% threshold, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues with direct human oral bioavailability measurements are ≥25%, mostly 50–90%, providing consistent affirmative evidence for F ≥ 20%. The mixed physicochemical prior is insufficient to overturn this experimental pattern.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself.",
    "Query's low logD and predominant ionization at physiological pH may reduce permeability, but no direct permeability data are available.",
    "Ester hydrolysis and first-pass metabolism of the query are not directly quantified.",
    "Some analogue values have wide ranges, but all remain above the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

